using System.Security.Claims;using HastaneRandevuSistemi.Data;using HastaneRandevuSistemi.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace HastaneRandevuSistemi.Controllers;[Authorize(Roles="Hasta")]public class PatientController:Controller{readonly HospitalContext db;public PatientController(HospitalContext d)=>db=d;public async Task<IActionResult> Index(){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var p=await db.Patients.Include(x=>x.User).Include(x=>x.Appointments).ThenInclude(x=>x.Doctor).ThenInclude(x=>x.User).Include(x=>x.MedicalRecords).ThenInclude(x=>x.Doctor).ThenInclude(x=>x.User).FirstAsync(x=>x.UserId==id);ViewBag.Branches=await db.Branches.Include(x=>x.Doctors).ThenInclude(x=>x.User).ToListAsync();return View(p);}[HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Book(int doctorId,DateTime appointmentDate,string appointmentTime,string note){var uid=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var p=await db.Patients.FirstAsync(x=>x.UserId==uid);if(appointmentDate.Date<DateTime.Today){TempData["Error"]="Geçmiş tarihe randevu alınamaz.";return RedirectToAction(nameof(Index));}if(await db.Appointments.AnyAsync(x=>x.DoctorId==doctorId&&x.AppointmentDate.Date==appointmentDate.Date&&x.AppointmentTime==appointmentTime&&x.Status!="İptal")){TempData["Error"]="Bu saat dolu.";return RedirectToAction(nameof(Index));}db.Appointments.Add(new Appointment{PatientId=p.Id,DoctorId=doctorId,AppointmentDate=appointmentDate.Date,AppointmentTime=appointmentTime,Status="Bekliyor",Note=note??""});await db.SaveChangesAsync();TempData["Success"]="Randevunuz oluşturuldu.";return RedirectToAction(nameof(Index));}[HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Cancel(int id){var uid=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var p=await db.Patients.FirstAsync(x=>x.UserId==uid);var a=await db.Appointments.FirstOrDefaultAsync(x=>x.Id==id&&x.PatientId==p.Id);if(a!=null){a.Status="İptal";await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
